package fitparser

import (
	"strconv"
	"strings"

	"github.com/muktihari/fit/profile/basetype"
	"github.com/muktihari/fit/profile/typedef"
)

// fitEnum is a FIT profile enum type as generated by the upstream profile
// package: an unsigned integer with a String method that returns the FIT
// profile name, or "<Type>Invalid(<n>)" for values the profile does not
// define.
type fitEnum interface {
	~uint8 | ~uint16 | ~uint32
	String() string
}

// enumName converts a FIT enum value into its profile name. The invalid
// sentinel becomes "". A value the profile does not define becomes
// "<snake>_<n>", e.g. "sport_42".
func enumName[T fitEnum](v, invalid T, snake string) string {
	if v == invalid {
		return ""
	}
	s := v.String()
	if s == "" || strings.Contains(s, "Invalid(") {
		return snake + "_" + strconv.FormatUint(uint64(v), 10)
	}
	return s
}

func sportName(v typedef.Sport) string {
	return enumName(v, typedef.SportInvalid, "sport")
}

func subSportName(v typedef.SubSport) string {
	return enumName(v, typedef.SubSportInvalid, "sub_sport")
}

