// productName resolves a device's product name: the free-form product_name
// string when set, otherwise the product profile name that the upstream
// GetProduct selects for the manufacturer (garmin_product for Garmin,
// Dynastream, Dynastream OEM and Tacx; favero_product for Favero), otherwise
// "".
func productName(name string, product uint16, getProduct func() (string, any)) string {
	if name != "" {
		return name
	}
	if product == basetype.Uint16Invalid {
		return ""
	}
	kind, v := getProduct()
	switch p := v.(type) {
	case typedef.GarminProduct:
		return enumName(p, typedef.GarminProductInvalid, kind)
	case typedef.FaveroProduct:
		return enumName(p, typedef.FaveroProductInvalid, kind)
	}
	return ""
}
